documents.text:
subscription Changes($domain: Domain) {
  onDataChanged(domain: $domain) {
    domain
    id
  }
}

mutation Retry($input: RetryInput!) {
  operations {
    retry(input: $input) {
      accepted
      state
      note
    }
  }
}

query Runs($state: RunState, $take: Int) {
  operations {
    runs(state: $state, take: $take) {
      id
      state
      name
    }
  }
}
